'use strict';
const scene=document.getElementById('scene'),reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
const motionGain=2.6;
const assetData=window.NOIR_ASSETS||{};
if(assetData.character)document.querySelector('.fallback').src=assetData.character;
let reverse=false,paused=reduced.matches,last=0,elapsed=0,impulse=0;
function setPause(value){paused=value;scene.dataset.motion=paused?'paused':'playing';}
let layoutBusy=false,desiredLayout=false,layoutTimer=0,copyTimer=0;
function applyLayout(){if(layoutBusy||desiredLayout===reverse)return;layoutBusy=true;reverse=desiredLayout;scene.dataset.layout=reverse?'reverse':'signal';scene.dataset.phase='geometry';scene.setAttribute('aria-busy','true');document.querySelector('meta[name="theme-color"]').content=reverse?'#18171f':'#e8e6eb';if(!paused)impulse=1;
 const update=()=>{document.getElementById('viewNumber').textContent=reverse?'02':'01';document.getElementById('viewName').textContent=reverse?'NIGHTFALL':'PALE HOUR';document.getElementById('announcement').textContent=reverse?'Dark composition selected':'Light composition selected';scene.dataset.phase='settle'};
 if(reduced.matches){update();layoutBusy=false;scene.dataset.phase='rest';scene.setAttribute('aria-busy','false');return}
 copyTimer=setTimeout(update,850);layoutTimer=setTimeout(()=>{layoutBusy=false;scene.dataset.phase='rest';scene.setAttribute('aria-busy','false');applyLayout()},2000);
}
function switchLayout(){desiredLayout=!desiredLayout;applyLayout()}
reduced.addEventListener('change',()=>{if(reduced.matches){clearTimeout(copyTimer);clearTimeout(layoutTimer);layoutBusy=false;reverse=!desiredLayout;applyLayout()}});
let touchStart=null,scrollGesture=false;scene.addEventListener('pointerdown',e=>{touchStart=[e.clientX,e.clientY];scrollGesture=false});scene.addEventListener('pointerup',e=>{scrollGesture=!!touchStart&&Math.hypot(e.clientX-touchStart[0],e.clientY-touchStart[1])>12;touchStart=null});scene.addEventListener('pointercancel',()=>{scrollGesture=true});
scene.addEventListener('click',event=>{if(scrollGesture){scrollGesture=false;return;}if(!event.target.closest('a')&&!window.getSelection()?.toString())switchLayout();});
scene.addEventListener('keydown',event=>{if(event.target!==scene||event.repeat)return;if(event.key==='Enter'||event.key===' '){event.preventDefault();switchLayout();}else if(event.key.toLowerCase()==='p'){setPause(!paused);document.getElementById('announcement').textContent=paused?'Clothing motion paused':'Clothing motion resumed';}});
reduced.addEventListener('change',event=>setPause(event.matches));setPause(paused);
const characterEl=document.querySelector('.character');let hoverRaf=0;
scene.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||reduced.matches||hoverRaf)return;const x=e.clientX,y=e.clientY;hoverRaf=requestAnimationFrame(()=>{const r=scene.getBoundingClientRect();characterEl.style.setProperty('--hx',((x-r.left)/r.width-.5)*30+'px');characterEl.style.setProperty('--hy',((y-r.top)/r.height-.5)*22+'px');hoverRaf=0;});});
scene.addEventListener('pointerleave',()=>{characterEl.style.setProperty('--hx','0px');characterEl.style.setProperty('--hy','0px');});
let tiltBase=null,tiltRaf=0;
function applyTilt(beta,gamma){if(reduced.matches)return;if(tiltBase===null)tiltBase=beta||0;const gx=Math.max(-24,Math.min(24,gamma||0)),by=Math.max(-24,Math.min(24,(beta||0)-tiltBase));characterEl.style.setProperty('--hx',(gx*1.15).toFixed(1)+'px');characterEl.style.setProperty('--hy',(by*.95).toFixed(1)+'px');}
if('DeviceOrientationEvent' in window)document.addEventListener('touchstart',function start(){document.removeEventListener('touchstart',start);const attach=()=>window.addEventListener('deviceorientation',e=>{if(tiltRaf)return;tiltRaf=requestAnimationFrame(()=>{applyTilt(e.beta,e.gamma);tiltRaf=0;});});if(typeof DeviceOrientationEvent.requestPermission==='function'){DeviceOrientationEvent.requestPermission().then(perm=>{if(perm==='granted')attach();}).catch(()=>{});}else attach();},{passive:true});
// Shared continuous mesh pins the seams of separately extracted RGBA parts.
