 let dirty=true;
 const resize=()=>{const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,1.7);canvas.width=Math.min(1400,Math.round(rect.width*dpr));canvas.height=Math.min(2600,Math.round(rect.height*dpr));gl.viewport(0,0,canvas.width,canvas.height);dirty=true;};new ResizeObserver(resize).observe(canvas);resize();
 document.addEventListener('visibilitychange',()=>{last=0;dirty=true;});window.addEventListener('resize',()=>{dirty=true;});scene.addEventListener('keydown',()=>{dirty=true;});reduced.addEventListener('change',()=>{dirty=true;});
 const render=now=>{const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(!paused&&!document.hidden){elapsed+=dt;impulse=Math.max(0,impulse-dt*.8);dirty=true;}if(dirty&&!document.hidden){gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform1f(t,elapsed);gl.uniform1f(strength,reduced.matches?0:motionGain*Math.min(elapsed/2,1)*(1+impulse*.4));for(const tex of textures){gl.bindTexture(gl.TEXTURE_2D,tex);gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);}dirty=false;}requestAnimationFrame(render);};
